import pytest

import click
from click.core import ParameterSource


def _requires_cli():
    @click.command()
    @click.option("--alpha", requires=["beta"])
    @click.option("--beta")
    def cli(alpha, beta):
        click.echo(f"ok {alpha} {beta}")

    return cli


def _conflicts_cli():
    @click.command()
    @click.option("--json", "as_json", is_flag=True, conflicts_with=["as_csv"])
    @click.option("--csv", "as_csv", is_flag=True)
    def cli(as_json, as_csv):
        click.echo(f"ok {as_json} {as_csv}")

    return cli


# --- Criterion 1: requires ---------------------------------------------------


def test_requires_missing_target_fails(runner):
    result = runner.invoke(_requires_cli(), ["--alpha", "1"])
    assert result.exit_code == 2
    assert "Error: Option '--alpha' requires '--beta'." in result.output


def test_requires_satisfied_on_command_line(runner):
    result = runner.invoke(_requires_cli(), ["--alpha", "1", "--beta", "2"])
    assert result.exit_code == 0, result.output
    assert "ok 1 2" in result.output


def test_requires_raises_usage_error_from_make_context():
    cli = _requires_cli()
    with pytest.raises(click.UsageError) as exc_info:
        cli.make_context("cli", ["--alpha", "1"])
    assert exc_info.value.format_message() == "Option '--alpha' requires '--beta'."


def test_requires_not_enforced_in_reverse(runner):
    # beta explicit, alpha not given: alpha's constraint does not apply.
    result = runner.invoke(_requires_cli(), ["--beta", "2"])
    assert result.exit_code == 0, result.output


def test_requires_multiple_reports_first_missing(runner):
    @click.command()
    @click.option("--alpha", requires=["beta", "gamma"])
    @click.option("--beta")
    @click.option("--gamma")
    def cli(alpha, beta, gamma):
        pass

    result = runner.invoke(cli, ["--alpha", "1"])
    assert result.exit_code == 2
    assert "Error: Option '--alpha' requires '--beta'." in result.output
    assert "'--gamma'" not in result.output

    result = runner.invoke(cli, ["--alpha", "1", "--beta", "2"])
    assert result.exit_code == 2
    assert "Error: Option '--alpha' requires '--gamma'." in result.output


def test_requires_display_uses_longest_option_string(runner):
    @click.command()
    @click.option("-a", "--alpha", requires=["beta"])
    @click.option("-b", "--beta")
    def cli(alpha, beta):
        pass

    result = runner.invoke(cli, ["-a", "1"])
    assert result.exit_code == 2
    assert "Error: Option '--alpha' requires '--beta'." in result.output


def test_display_tie_uses_first_longest_option_string(runner):
    @click.command()
    @click.option("-x", "--xx", "--yy", "alpha", requires=["beta"])
    @click.option("--beta")
    def cli(alpha, beta):
        pass

    result = runner.invoke(cli, ["--yy", "1"])
    assert result.exit_code == 2
    assert "Error: Option '--xx' requires '--beta'." in result.output


def test_violations_reported_in_declaration_order(runner):
    @click.command()
    @click.option("--alpha", requires=["beta"])
    @click.option("--beta")
    @click.option("--gamma", requires=["delta"])
    @click.option("--delta")
    def cli(alpha, beta, gamma, delta):
        pass

    # gamma given first on the command line, but alpha is declared first.
    result = runner.invoke(cli, ["--gamma", "1", "--alpha", "2"])
    assert result.exit_code == 2
    assert "Error: Option '--alpha' requires '--beta'." in result.output
    assert "--gamma' requires" not in result.output


def test_negative_flag_counts_as_explicit(runner):
    @click.command()
    @click.option("--alpha", requires=["beta"])
    @click.option("--beta/--no-beta", default=False)
    def cli(alpha, beta):
        click.echo(f"ok {beta}")

    result = runner.invoke(cli, ["--alpha", "1", "--no-beta"])
    assert result.exit_code == 0, result.output
    assert "ok False" in result.output


def test_prompted_value_counts_as_explicit(runner):
    @click.command()
    @click.option("--alpha", requires=["beta"])
    @click.option("--beta", prompt=True)
    def cli(alpha, beta):
        click.echo(f"ok {alpha} {beta}")

    result = runner.invoke(cli, ["--alpha", "1"], input="2\n")
    assert result.exit_code == 0, result.output
    assert "ok 1 2" in result.output


def test_resilient_parsing_skips_constraints():
    cli = _requires_cli()
    ctx = cli.make_context("cli", ["--alpha", "1"], resilient_parsing=True)
    assert ctx.params["alpha"] == "1"

    cli2 = _conflicts_cli()
    ctx2 = cli2.make_context("cli", ["--json", "--csv"], resilient_parsing=True)
    assert ctx2.params["as_json"] is True
    assert ctx2.params["as_csv"] is True


# --- Criterion 2: conflicts_with ---------------------------------------------


def test_conflicts_with_both_explicit_fails(runner):
    result = runner.invoke(_conflicts_cli(), ["--json", "--csv"])
    assert result.exit_code == 2
    assert "Error: Option '--json' cannot be used with '--csv'." in result.output


def test_conflicts_with_only_one_given_succeeds(runner):
    cli = _conflicts_cli()
    result = runner.invoke(cli, ["--json"])
    assert result.exit_code == 0, result.output
    assert "ok True False" in result.output

    result = runner.invoke(cli, ["--csv"])
    assert result.exit_code == 0, result.output
    assert "ok False True" in result.output


def test_conflicts_with_raises_usage_error():
    cli = _conflicts_cli()
    with pytest.raises(click.UsageError) as exc_info:
        cli.make_context("cli", ["--csv", "--json"])
    assert (
        exc_info.value.format_message()
        == "Option '--json' cannot be used with '--csv'."
    )


def test_conflicts_checked_before_requires(runner):
    @click.command()
    @click.option("--alpha", conflicts_with=["beta"], requires=["beta"])
    @click.option("--beta")
    def cli(alpha, beta):
        pass

    result = runner.invoke(cli, ["--alpha", "1", "--beta", "2"])
    assert result.exit_code == 2
    assert "Error: Option '--alpha' cannot be used with '--beta'." in result.output
    assert "requires" not in result.output

    result = runner.invoke(cli, ["--alpha", "1"])
    assert result.exit_code == 2
    assert "Error: Option '--alpha' requires '--beta'." in result.output


def test_conflict_before_requires_across_different_targets(runner):
    @click.command()
    @click.option("--alpha", requires=["gamma"], conflicts_with=["beta"])
    @click.option("--beta")
    @click.option("--gamma")
    def cli(alpha, beta, gamma):
        pass

    result = runner.invoke(cli, ["--alpha", "1", "--beta", "2"])
    assert result.exit_code == 2
    assert "Error: Option '--alpha' cannot be used with '--beta'." in result.output
    assert "requires" not in result.output


# --- Criterion 3: defaults / default_map -------------------------------------


def test_default_owner_does_not_trigger_requires(runner):
    @click.command()
    @click.option("--alpha", requires=["beta"], default="x")
    @click.option("--beta")
    def cli(alpha, beta):
        click.echo(f"ok {alpha}")

    result = runner.invoke(cli, [])
    assert result.exit_code == 0, result.output
    assert "ok x" in result.output


def test_default_does_not_satisfy_requires(runner):
    @click.command()
    @click.option("--alpha", requires=["beta"])
    @click.option("--beta", default="y")
    def cli(alpha, beta):
        pass

    result = runner.invoke(cli, ["--alpha", "1"])
    assert result.exit_code == 2
    assert "Error: Option '--alpha' requires '--beta'." in result.output


def test_default_map_does_not_satisfy_requires(runner):
    @click.command(context_settings={"default_map": {"beta": "y"}})
    @click.option("--alpha", requires=["beta"])
    @click.option("--beta")
    def cli(alpha, beta):
        pass

    result = runner.invoke(cli, ["--alpha", "1"])
    assert result.exit_code == 2
    assert "Error: Option '--alpha' requires '--beta'." in result.output


def test_default_map_owner_does_not_trigger_requires(runner):
    @click.command(context_settings={"default_map": {"alpha": "x"}})
    @click.option("--alpha", requires=["beta"])
    @click.option("--beta")
    def cli(alpha, beta):
        click.echo(f"ok {alpha}")

    result = runner.invoke(cli, [])
    assert result.exit_code == 0, result.output
    assert "ok x" in result.output


def test_default_and_default_map_do_not_trigger_conflicts(runner):
    @click.command(context_settings={"default_map": {"as_csv": True}})
    @click.option(
        "--json", "as_json", is_flag=True, default=True, conflicts_with=["as_csv"]
    )
    @click.option("--csv", "as_csv", is_flag=True)
    def cli(as_json, as_csv):
        click.echo(f"ok {as_json} {as_csv}")

    # both values come from default / default_map
    result = runner.invoke(cli, [])
    assert result.exit_code == 0, result.output
    assert "ok True True" in result.output

    # owner explicit, target only from default_map: no conflict
    result = runner.invoke(cli, ["--json"])
    assert result.exit_code == 0, result.output

    # target explicit, owner only from default: no conflict
    result = runner.invoke(cli, ["--csv"])
    assert result.exit_code == 0, result.output


# --- Criterion 4: envvar counts as explicit ----------------------------------


def test_envvar_satisfies_requires(runner):
    @click.command()
    @click.option("--alpha", requires=["beta"])
    @click.option("--beta", envvar="CONSTRAINT_TEST_BETA")
    def cli(alpha, beta):
        click.echo(f"ok {alpha} {beta}")

    result = runner.invoke(
        cli, ["--alpha", "1"], env={"CONSTRAINT_TEST_BETA": "2"}
    )
    assert result.exit_code == 0, result.output
    assert "ok 1 2" in result.output


def test_envvar_owner_triggers_requires(runner):
    @click.command()
    @click.option("--alpha", envvar="CONSTRAINT_TEST_ALPHA", requires=["beta"])
    @click.option("--beta")
    def cli(alpha, beta):
        pass

    result = runner.invoke(cli, [], env={"CONSTRAINT_TEST_ALPHA": "1"})
    assert result.exit_code == 2
    assert "Error: Option '--alpha' requires '--beta'." in result.output


def test_envvar_triggers_conflict(runner):
    @click.command()
    @click.option("--alpha", conflicts_with=["beta"])
    @click.option("--beta", envvar="CONSTRAINT_TEST_BETA")
    def cli(alpha, beta):
        pass

    result = runner.invoke(
        cli, ["--alpha", "1"], env={"CONSTRAINT_TEST_BETA": "2"}
    )
    assert result.exit_code == 2
    assert "Error: Option '--alpha' cannot be used with '--beta'." in result.output


# --- Criterion 5: unknown target ---------------------------------------------


def test_unknown_requires_target_raises_type_error():
    @click.command()
    @click.option("--alpha", requires=["zzz"])
    def cli(alpha):
        pass

    with pytest.raises(TypeError) as exc_info:
        cli.make_context("cli", ["--alpha", "1"])
    assert str(exc_info.value) == "Option 'alpha' refers to unknown parameter 'zzz'."


def test_unknown_conflicts_target_raises_type_error():
    @click.command()
    @click.option("--alpha", conflicts_with=["zzz"])
    @click.option("--beta")
    def cli(alpha, beta):
        pass

    with pytest.raises(TypeError) as exc_info:
        cli.make_context("cli", ["--alpha", "1"])
    assert str(exc_info.value) == "Option 'alpha' refers to unknown parameter 'zzz'."


def test_unknown_target_not_checked_when_owner_not_explicit():
    @click.command()
    @click.option("--alpha", requires=["zzz"])
    @click.option("--beta")
    def cli(alpha, beta):
        pass

    ctx = cli.make_context("cli", ["--beta", "2"])
    assert ctx.get_parameter_source("alpha") == ParameterSource.DEFAULT
    assert ctx.params["beta"] == "2"


# --- Criterion 6: init validation --------------------------------------------


def test_requires_string_raises_type_error():
    with pytest.raises(TypeError) as exc_info:
        click.Option(["--alpha"], requires="beta")
    assert (
        str(exc_info.value)
        == "'requires' must be a sequence of parameter names, not a string."
    )


def test_conflicts_with_string_raises_type_error():
    with pytest.raises(TypeError) as exc_info:
        click.Option(["--alpha"], conflicts_with="beta")
    assert (
        str(exc_info.value)
        == "'conflicts_with' must be a sequence of parameter names, not a string."
    )


def test_requires_self_reference_raises_value_error():
    with pytest.raises(ValueError) as exc_info:
        click.Option(["--alpha"], requires=["alpha"])
    assert str(exc_info.value) == "Option 'alpha' cannot refer to itself."


def test_conflicts_with_self_reference_raises_value_error():
    with pytest.raises(ValueError) as exc_info:
        click.Option(["--alpha"], conflicts_with=["alpha"])
    assert str(exc_info.value) == "Option 'alpha' cannot refer to itself."


def test_constraints_stored_as_tuples():
    opt = click.Option(["--alpha"], requires=["beta", "gamma"], conflicts_with=["delta"])
    assert opt.requires == ("beta", "gamma")
    assert opt.conflicts_with == ("delta",)


# --- Criterion 7: constraint-free commands unaffected ------------------------


def test_constraint_defaults_are_empty_tuples():
    opt = click.Option(["--alpha"])
    assert opt.requires == ()
    assert opt.conflicts_with == ()


def test_constraint_free_command_unaffected(runner):
    @click.command(context_settings={"default_map": {"gamma": "g"}})
    @click.option("--alpha")
    @click.option("--beta", default="b")
    @click.option("--gamma")
    @click.option("--flag/--no-flag", default=False)
    def cli(alpha, beta, gamma, flag):
        click.echo(f"{alpha} {beta} {gamma} {flag}")

    result = runner.invoke(cli, ["--alpha", "1", "--no-flag"])
    assert result.exit_code == 0, result.output
    assert result.output == "1 b g False\n"

    result = runner.invoke(cli, ["--alpha", "1", "extra"])
    assert result.exit_code == 2
    assert "Got unexpected extra argument (extra)" in result.output


def test_constraint_free_option_info_dict_has_no_new_keys():
    opt = click.Option(["--alpha"])
    info = opt.to_info_dict()
    assert "requires" not in info
    assert "conflicts_with" not in info


def test_option_subclass_without_new_kwargs_still_works(runner):
    class MyOption(click.Option):
        def __init__(self, *args, **kwargs):
            kwargs.setdefault("help", "custom")
            super().__init__(*args, **kwargs)

    @click.command()
    @click.option("--alpha", cls=MyOption)
    def cli(alpha):
        click.echo(alpha)

    result = runner.invoke(cli, ["--alpha", "v"])
    assert result.exit_code == 0, result.output
    assert result.output == "v\n"
